"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { ShoppingBag, Tag, Bell } from "lucide-react";
import { motion, useMotionValue, useTransform, animate } from "framer-motion";
import { cn } from "@/lib/utils";

const TABS = ["all", "orders", "promotions"] as const;
type TabType = typeof TABS[number];

export default function NotificationsPage() {
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  const x = useMotionValue(0);

  // 1. Handle Responsive Width
  useEffect(() => {
    const updateWidth = () => {
      if (containerRef.current)
        setContainerWidth(containerRef.current.offsetWidth);
    };
    updateWidth();
    window.addEventListener("resize", updateWidth);
    return () => window.removeEventListener("resize", updateWidth);
  }, []);

  // 2. Tab Indicator Animation
  const indicatorX = useTransform(
    x,
    [0, -containerWidth * (TABS.length - 1)],
    ["0%", `${(TABS.length - 1) * 100}%`]
  );

  const handleTabClick = (index: number) => {
    setActiveIndex(index);
    animate(x, -index * containerWidth, {
      type: "spring",
      bounce: 0,
      duration: 0.4,
    });
  };

  const handleDragEnd = (_: any, info: any) => {
    const swipeThreshold = 50;
    const velocityThreshold = 500;

    if (
      info.offset.x < -swipeThreshold ||
      info.velocity.x < -velocityThreshold
    ) {
      if (activeIndex < TABS.length - 1) {
        handleTabClick(activeIndex + 1);
        return;
      }
    }
    if (info.offset.x > swipeThreshold || info.velocity.x > velocityThreshold) {
      if (activeIndex > 0) {
        handleTabClick(activeIndex - 1);
        return;
      }
    }
    handleTabClick(activeIndex);
  };

  return (
    <div className="h-full flex flex-col bg-background text-foreground overflow-x-hidden md:pt-20">
      <header className="sticky top-0 z-20 border-b border-foreground/10 bg-background/80 backdrop-blur-md">
        <div className="mx-auto px-4 relative">
          <nav className="flex w-full">
            {TABS.map((tab, i) => (
              <button
                key={tab}
                onClick={() => handleTabClick(i)}
                className={cn(
                  "flex-1 py-4 text-sm font-medium capitalize transition-colors outline-none",
                  activeIndex === i ? "text-foreground" : "text-foreground/40"
                )}
              >
                {tab}
              </button>
            ))}
          </nav>
          <motion.div
            style={{ x: indicatorX, width: `${100 / TABS.length}%` }}
            className="absolute bottom-0 left-0 px-4"
          >
            <div className="h-0.5 bg-foreground w-full rounded-full" />
          </motion.div>
        </div>
      </header>

      <main
        className="max-h-[80vh] max-w-screen flex-1 mx-auto w-full relative overflow-y-scroll overflow-x-hidden pb-10 bg-"
        ref={containerRef}
      >
        <motion.div
          drag="x"
          dragConstraints={{
            left: -containerWidth * (TABS.length - 1),
            right: 0,
          }}
          style={{ x }}
          onDragEnd={handleDragEnd}
          className="h-full flex items-start touch-pan-y cursor-grab active:cursor-grabbing"
        >
          {TABS.map((tabType, i) => (
            <TabSection
              key={tabType}
              type={tabType}
              isActive={activeIndex === i}
            />
          ))}
        </motion.div>
      </main>
    </div>
  );
}

function TabSection({
  type,
  isActive,
}: {
  type: TabType;
  isActive: boolean;
}) {
  return (
    <section className="w-full shrink-0 h-full bg-amber-600">
      <motion.div
        animate={{
          opacity: isActive ? 1 : 0.4,
        }}
        transition={{ type: "spring", bounce: 0, duration: 0.4 }}
        className="h-full"
      >
        <NotificationList type={type} />
      </motion.div>
    </section>
  );
}

function NotificationList({ type }: { type: TabType }) {
  const notifications = useMemo(() => {
    if (type === "all") return MOCK_NOTIFICATIONS;
    return MOCK_NOTIFICATIONS.filter((n) =>
      type === "orders" ? n.type === "order" : n.type === "promo"
    );
  }, [type]);

  if (notifications.length === 0) {
    return (
      <div className="h-full py-24 text-center text-foreground/40">
        <Bell className="mx-auto mb-4 opacity-10" size={48} />
        <p className="text-sm">No {type} notifications yet</p>
      </div>
    );
  }

  return (
    <div className="divide-y divide-foreground/10 h-full">
      {notifications.map((n) => (
        <div
          key={n.id}
          className="flex gap-4 p-5 hover:bg-foreground/5 transition-colors"
        >
          <div className="shrink-0 w-11 h-11 flex items-center justify-center rounded-full bg-foreground text-background">
            {n.type === "order" ? <ShoppingBag size={20} /> : <Tag size={20} />}
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-start">
              <h3 className="text-[14px] font-semibold tracking-tight">
                {n.title}
              </h3>
              <span className="text-[10px] font-medium text-foreground/40 uppercase">
                {n.timestamp}
              </span>
            </div>
            <p className="text-[13px] text-foreground/60 mt-1 leading-relaxed">
              {n.message}
            </p>
          </div>
        </div>
      ))}
    </div>
  );
}


